\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath}
\usepackage{amssymb}

\title{Lecture Notes: Conservation Laws in Continuum Mechanics}
\author{Department of Applied Mathematics}
\date{Spring 2026}

\begin{document}
\maketitle

\section{Mass and Momentum}
The integral balance laws for a material volume read
\begin{eqnarray}
\frac{d}{dt}\int_V \rho \, dV &=& 0 \label{eq:mass}\\
\frac{d}{dt}\int_V \rho \mathbf{v} \, dV &=& \int_{\partial V} \mathbf{t} \, dA + \int_V \rho \mathbf{b} \, dV \label{eq:momentum}
\end{eqnarray}
where $\mathbf{t}$ is the traction and $\mathbf{b}$ the body force.

\section{Energy}
The mechanical energy balance follows by contracting the momentum
equation with the velocity field:
\begin{eqnarray*}
\frac{dK}{dt} + \frac{d}{dt}\int_V \rho e \, dV &=& \int_{\partial V} \mathbf{t}\cdot\mathbf{v} \, dA + \int_V \rho \mathbf{b}\cdot\mathbf{v} \, dV
\end{eqnarray*}

\section{Local Forms}
Localisation yields the differential statements
\begin{eqnarray}
\dot{\rho} + \rho \, \nabla\cdot\mathbf{v} &=& 0 \label{eq:localmass}\\
\rho \, \dot{\mathbf{v}} &=& \nabla\cdot\boldsymbol{\sigma} + \rho \mathbf{b} \label{eq:localmom}
\end{eqnarray}
which hold at every regular point of the continuum.
\end{document}

